Given a string s and a non negative integer k, find the length of the longest substring that contains exactly k distinct characters. If no such substring exists, return -1.Examples: Input: s = "aabacbebebe", k = 3Output: 7Explanation: The longest substring with exactly 3 distinct characters is "cbebebe", which includes 'c', 'b', and 'e'.Input: s = "aaaa", k = 2Output: -1Explanation: The string contains only one unique character, so there's no substring with 2 distinct characters.Input: s = "aabaaab", k = 2Output: 7Explanation: The entire string "aabaaab" has exactly 2 unique characters 'a' and 'b', making it the longest valid substring.Try It YourselfTable of Content[Naive Approach] Using nested loops with a hash set - O(n^2) Time and O(1) Space[Better Approach] Using  Prefix Sum and Binary Search - O(n*log n) Time and O(n) Space [Expected Approach] Sliding Window with Frequency Count - O(n) Time and O(1) Space[Naive Approach] Using nested loops with a hash set - O(n^2) Time and O(1) SpaceThis brute-force approach checks all substrings starting from each index. It uses a set to track unique characters, and whenever a substring has exactly k distinct characters, it updates the maximum length. 
            C++

    #include <iostream>
#include <unordered_set>
#include <string>
#include <algorithm>
using namespace std;

int longestKSubstr(const string& s, int k) {
    int ans = -1;  

    // set to track unique characters in current substring
    unordered_set<char> st;  


    for (int i = 0; i < s.size(); i++) {

        // reset the set for a new starting index - 'i'
        st.clear();  

        // expand the substring from index i to j
        for (int j = i; j < s.size(); j++) {
            st.insert(s[j]); 

            // number of unique characters becomes exactly k,
            if (st.size() == k) {
                ans = max(ans, j - i + 1);
            }

            if(st.size() > k) break;
        }
    }

    return ans;
}

int main() {
    string s = "aabacbebebe";
    int k = 3;

    cout << longestKSubstr(s, k) << '\n'; 
    return 0;
}


