            C++

    #include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int longestKSubstr(const string& s, int k) {
    int n = s.size();

    // prefix frequency array: vec[i][ch] = 
    // frequency of char 'a'+ch in s[0..i]
    vector<vector<int>> vec(n, vector<int>(26, 0));

    for (int i = 0; i < n; i++) {
        vec[i][s[i] - 'a']++;
        if (i > 0) {
            for (int j = 0; j < 26; j++) {
                vec[i][j] += vec[i - 1][j];
            }
        }
    }

    int ans = -1;

    // try for each starting index
    for (int i = 0; i < n; i++) {

        // search space is from [i to n-1]
        int low = i, high = n - 1, currAns = -1;

        while (low <= high) {
            int mid = (low + high) / 2;
            int count = 0;
            vector<int> freq = vec[mid];

            // remove prefix before i if needed
            if (i > 0) {
                for (int j = 0; j < 26; j++) {
                    freq[j] -= vec[i - 1][j];
                }
            }

            // freq[j] -> represents the count of char('a' + j) in 
            // the subtring starting from i and ending at mid 

            for (int j = 0; j < 26; j++) {

                // if char(j+'a') has a frequency
                if (freq[j] > 0) count++;
            }

            if (count == k) {
                currAns = mid - i + 1;
                low = mid + 1;
            } else if (count < k) {
                low = mid + 1;
            } else {
                high = mid - 1;
            }
        }

        if (currAns != -1) {
            ans = max(ans, currAns);
        }
    }

    return ans;
}

int main() {
    string s = "aabacbebebe";
    int k = 3;
    cout << longestKSubstr(s, k) << '\n';
    return 0;
}


